private Object[] dummyArgsFor(String pattern) {
    int maxIndex = placeholders(pattern).stream()
        .mapToInt(Integer::parseInt)
        .max()
        .orElse(-1);

    Object[] args = new Object[maxIndex + 1];

    for (int i = 0; i < args.length; i++) {
        args[i] = "X" + i;
    }

    return args;
}
